script:
// Independent implementation of the public protocol observed in Copy 1.4.85.
// Identity URLs remain stable; only the configured official API receives requests.
var WEB = 'https://www.copy4000.com';
var API_HOSTS = ['api.mangacopy.com','mapi.copy20.com','mapi.copy2000.site','api.2026copy.com','api.copy3000.com','api.copy4000.com'];
var ID_HOSTS = API_HOSTS.concat(['www.mangacopy.com','www.copy20.com','www.2026copy.com','www.copy3000.com','www.copy4000.com']);
function fail(message) { throw new Error('拷贝漫画：' + message); }
function obj(v) { return v !== null && typeof v === 'object' && !Array.isArray(v); }
function str(v) { return typeof v === 'string' ? v : ''; }
function count(v) { return typeof v === 'number' && isFinite(v) && v >= 0 && Math.floor(v) === v; }
function key(v) { return typeof v === 'string' && /^[A-Za-z0-9_-]+$/.test(v) && v.length <= 256; }
function opts(v) { return obj(v) ? v : {}; }
function pageOffset(page) { if (!count(page) || page < 1) fail('无效页码'); return (page - 1) * 21; }
function apiHost(options) {
  var host = options.apiDomain === undefined ? 'api.copy4000.com' : options.apiDomain;
  if (API_HOSTS.indexOf(host) < 0) fail('请选择官方 Copy API 域名');
  return host;
}
function requestHeaders(options) {
  var h = {'Accept':'application/json','Accept-Language':'en-US,en;q=0.9,zh-TW;q=0.8,zh;q=0.7','Origin':'https://2025copy.com','Version':'2026.08.21','Region':'0','Webp':'0','User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:109.0) Gecko/20100101 Firefox/114.0','sec-fetch-dest':'document','sec-fetch-mode':'navigate','sec-fetch-site':'same-origin','sec-fetch-user':'?1','upgrade-insecure-requests':'1'};
  var uaMode = choice(options.userAgentMode || 'custom',['custom','desktop','mobile','app','none'],'userAgentMode');
  if (uaMode === 'app') delete h['User-Agent'];
  else if (uaMode === 'none') h['User-Agent'] = '';
  else if (uaMode === 'custom' && options.userAgent !== undefined) {
    if (!str(options.userAgent).trim() || /[\r\n]/.test(options.userAgent)) fail('无效 User-Agent');
    h['User-Agent'] = options.userAgent;
  }
  // Native host resolves desktop/mobile/app commands; never send commands as UA.
  var platform = options.platform === undefined ? '1' : String(options.platform);
  if (['',' ','1','2','3','4','5'].indexOf(platform) < 0) fail('无效 platform');
  if (platform !== '') h.platform = platform;
  return h;
}
async function api(path, options) {
  var url = 'https://' + apiHost(options) + '/api/v3' + path;
  var response = await triomi.fetch(url,{method:'GET',headers:requestHeaders(options)});
  if (response.status === 401 || response.status === 403) fail('登录失效或无权访问（HTTP ' + response.status + '）');
  if (response.status !== 200) fail('HTTP ' + response.status);
  if (typeof response.body !== 'string' || response.body.length > 16777216) fail('API 响应过大或无效');
  var body;
  try { body = JSON.parse(response.body); } catch (e) { fail('API 未返回有效 JSON'); }
  if (!obj(body) || body.code !== 200 || !obj(body.results)) fail('API 请求失败（' + (obj(body) ? String(body.code) : '无效响应') + '）');
  return body.results;
}
function identityPath(url) {
  if (typeof url !== 'string') fail('缺少作品地址');
  var match = /^https:\/\/([^/?#]+)(\/[^#]*)$/.exec(url);
  if (match) {
    if (ID_HOSTS.indexOf(match[1]) < 0) fail('无效作品域名');
    return match[2].replace(/^\/api\/v3/, '');
  }
  if (url.charAt(0) === '/') return url;
  if (/^[A-Za-z0-9_-]+\/(?:chapter|chapter2)\//.test(url)) return '/comic/' + url;
  fail('无效作品地址');
}
function comicIdentity(url) {
  var m = /^\/comic2?\/([A-Za-z0-9_-]+)\/?$/.exec(identityPath(url));
  if (!m || !key(m[1])) fail('无效作品标识');
  return m[1];
}
function chapterIdentity(url) {
  var m = /^\/comic\/([A-Za-z0-9_-]+)\/(?:chapter|chapter2)\/([A-Za-z0-9_-]+)\/?$/.exec(identityPath(url));
  if (!m || !key(m[1]) || !key(m[2])) fail('无效章节标识');
  return {slug:m[1],uuid:m[2]};
}
function imageUrl(url, options) {
  if (typeof url !== 'string' || url.length > 8192 || !/^https:\/\/[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+(?:\/[^\s\\]*)?$/.test(url)) fail('图片地址无效');
  var resolution = options.resolution === undefined ? '1500' : String(options.resolution);
  if (['800','1200','1500'].indexOf(resolution) < 0) fail('无效图片分辨率');
  return url.replace(/\d+(?=x\.(?:jpg|webp)$)/, resolution);
}
function names(rows) {
  if (!Array.isArray(rows)) return [];
  return rows.map(function(row) { return obj(row) ? str(row.name) : ''; }).filter(function(name) { return name.length > 0; });
}
function media(comic, options) {
  if (!obj(comic) || !key(comic.path_word) || !str(comic.name)) fail('作品数据缺少标识或标题');
  var tags = names(comic.theme);
  if (obj(comic.region) && str(comic.region.display)) tags.unshift(comic.region.display);
  var status = obj(comic.status) ? comic.status.value : undefined;
  return {remoteId:comic.path_word,type:'manga',title:comic.name,url:WEB+'/comic/'+comic.path_word,coverUrl:comic.cover ? imageUrl(comic.cover,options) : null,author:names(comic.author).join(', '),description:str(comic.brief),tags:tags,status:status===0?'ongoing':status===1||status===2?'completed':'unknown'};
}
function listRows(result, options, wrapped) {
  if (!Array.isArray(result.list)) fail('API 列表无效');
  return result.list.map(function(row) { return media(wrapped ? row.comic : row, options); });
}
function query(parts, name, value) { parts.push(name+'='+encodeURIComponent(value)); }
function choice(value, allowed, label) { if (allowed.indexOf(value) < 0) fail('无效筛选：'+label); return value; }
async function discover(url, page, options) {
  options = opts(options);
  var offset = pageOffset(page), path = identityPath(url), route;
  // Feed URLs are selectors, not request targets. Offset is always 21-based.
  if (/^\/(?:api\/v3\/)?update\/newest(?:\?|$)/.test(path)) route = '/update/newest';
  else if (/^\/recs(?:\?|$)/.test(path)) route = '/recs';
  else if (/^\/ranks(?:\?|$)/.test(path)) route = '/ranks';
  else if (/^\/member\/collect\/comics(?:\?|$)/.test(path)) route = '/member/collect/comics';
  else if (/^\/comics(?:\?|$)/.test(path)) route = '/comics';
  else fail('未知浏览列表');
  if (route === '/update/newest' && choice(options.latestMode || 'updated',['updated','new'],'latestMode') === 'updated') route = '/comics';
  if (route === '/comics' || route === '/member/collect/comics') {
    var feedOptions = {};
    Object.keys(options).forEach(function(k) { feedOptions[k] = options[k]; });
    feedOptions.filters = Object.assign({}, opts(options.filters));
    if (route === '/member/collect/comics') feedOptions.filters.collect = true;
    else if (!feedOptions.filters.ordering) feedOptions.filters.ordering = /ordering=-popular/.test(path) ? '-popular' : '-datetime_updated';
    return search('',page,feedOptions);
  }
  var suffix = '?limit=21&offset='+offset;
  if (route === '/recs') suffix = '?pos=3200102&limit=21&offset='+offset;
  if (route === '/ranks') {
    var filters = opts(options.filters);
    suffix = '?type=1&limit=21&offset='+offset+'&date_type='+choice(filters.rank || 'total',['day','week','month','total'],'rank')+'&audience_type='+choice(filters.audience || 'male',['male','female'],'audience')+'&_update=true';
  }
  return listRows(await api(route+suffix,options),options,true);
}
async function search(queryText, page, options) {
  options = opts(options);
  var f = opts(options.filters), parts = ['limit=21','offset='+pageOffset(page)], route = '/comics', wrapped = false;
  if (typeof queryText !== 'string') fail('无效搜索文本');
  if (queryText.trim()) {
    route = '/search/comic';
    query(parts,'q',queryText);
    query(parts,'q_type',choice(f.qType || '',['','name','author','local'],'qType'));
  } else if (f.collect === true) {
    route = '/member/collect/comics'; wrapped = true;
    query(parts,'ordering','-datetime_modifier');
  } else if (f.rank || f.audience) {
    route = '/ranks'; wrapped = true;
    query(parts,'type','1');
    query(parts,'date_type',choice(f.rank || '',['','day','week','month','total'],'rank'));
    query(parts,'audience_type',choice(f.audience || 'male',['male','female'],'audience'));
  } else {
    if (f.region) query(parts,'top',choice(f.region,['japan','korea','west','finish'],'region'));
    if (f.theme) { if (!key(f.theme)) fail('无效主题'); query(parts,'theme',f.theme); }
    if (f.freeType) query(parts,'free_type',choice(String(f.freeType),['1','2'],'freeType'));
    query(parts,'ordering',choice(f.ordering || '-datetime_updated',['popular','-popular','datetime_updated','-datetime_updated'],'ordering'));
  }
  query(parts,'_update','true');
  return listRows(await api(route+'?'+parts.join('&'),options),options,wrapped);
}
async function searchTags(options) {
  options = opts(options);
  var result = await api('/theme/comic/count?limit=100',options);
  if (!Array.isArray(result.list)) fail('主题列表无效');
  return result.list.map(function(row) {
    if (!obj(row) || !key(row.path_word) || !str(row.name)) fail('主题数据无效');
    return {id:row.path_word,label:row.name+(count(row.count)?' ('+row.count+')':'')};
  });
}
async function searchTagged(queryText, page, tags, options) {
  if (!Array.isArray(tags) || tags.length > 1) fail('Copy API 每次仅支持一个主题');
  options = Object.assign({},opts(options));
  options.filters = Object.assign({},opts(options.filters));
  if (tags.length) options.filters.theme = tags[0];
  return search(queryText,page,options);
}
async function detail(url, item, options) {
  options = opts(options);
  var slug = comicIdentity(url), result = await api('/comic2/'+slug,options);
  if (!obj(result.comic) || result.comic.path_word !== slug || !obj(result.groups)) fail('作品详情标识或分组无效');
  var chapters = [], seen = {}, hidden = str(options.hideChapters).split('\n'), groups = Object.keys(result.groups);
  for (var g = 0; g < groups.length; g++) {
    var group = result.groups[groups[g]];
    if (!obj(group) || !key(group.path_word)) fail('章节分组无效');
    var rows = [], total = null;
    for (var offset = 0; total === null || offset < total; offset += 100) {
      var response = await api('/comic/'+slug+'/group/'+group.path_word+'/chapters?limit=100&offset='+offset+'&_update=true',options);
      if (!Array.isArray(response.list) || !count(response.total) || response.total > 20000 || (response.offset !== undefined && response.offset !== offset)) fail('章节分页无效');
      total = response.total;
      if (response.list.length === 0 && offset < total) fail('章节目录不完整');
      for (var n = 0; n < response.list.length; n++) {
        var row = response.list[n];
        if (!obj(row) || !key(row.uuid) || !str(row.name) || !count(row.index) || row.comic_path_word !== slug || (row.group_path_word && row.group_path_word !== group.path_word) || seen[row.uuid]) fail('章节标识、分组或分页重复');
        seen[row.uuid] = true; rows.push(row);
      }
      if (rows.length > 20000 || chapters.length + rows.length > 20000) fail('章节目录过大');
    }
    if (rows.length !== total) fail('章节目录数量不符');
    // Triomi next-chapter navigation advances directory index, unlike Mihon.
    rows.sort(function(a,b) { return a.index-b.index; });
    rows.forEach(function(row) {
      if (hidden.indexOf(row.name) >= 0) return;
      chapters.push({remoteId:slug+'/'+row.uuid,title:(group.path_word==='default'?'':str(group.name)+'：')+row.name,url:WEB+'/comic/'+slug+'/chapter/'+row.uuid,volumeTitle:str(group.name),releaseDate:str(row.datetime_created)});
    });
  }
  if (options.showMangaComments === true) {
    if (!key(result.comic.uuid)) fail('作品评论标识缺失');
    chapters.push({remoteId:slug+'/comments',title:'漫畫評論',url:WEB+'/commentList?comicId='+result.comic.uuid,volumeTitle:'評論'});
  }
  return {item:media(result.comic,options),chapters:chapters};
}
async function comments(path, options, chapterComments) {
  var requestOptions = options;
  if (chapterComments && options.commentApiDomain) {
    requestOptions = Object.assign({},options,{apiDomain:options.commentApiDomain});
  }
  var result = await api(path,requestOptions), rows = result.list;
  if (!Array.isArray(rows)) fail('评论列表无效');
  var regexes = [], seen = {}, out = [];
  if (options.commentRegex) {
    str(options.commentRegex).split('\n').forEach(function(line) {
      line = line.trim();
      if (!line) return;
      try { regexes.push(new RegExp(line)); } catch (e) { fail('评论屏蔽正则表达式无效'); }
    });
  }
  rows.forEach(function(row) {
    if (!obj(row) || typeof row.comment !== 'string' || typeof row.user_name !== 'string') fail('评论数据无效');
    if (regexes.some(function(regex) { return regex.test(row.comment); })) return;
    var dedup = row.user_name+' : '+row.comment;
    if (chapterComments && seen[dedup]) return;
    seen[dedup] = true;
    out.push({author:row.user_name,text:row.comment,replyTo:str(row.parent_user_name)});
  });
  if (chapterComments && options.reverseChapterComments === true) out.reverse();
  return out;
}
function commentMode(options) { return choice(options.commentMode || 'separate',['separate','merge'],'commentMode'); }
async function content(url, chapter, options) {
  options = opts(options);
  var commentMatch = /^\/commentList\?comicId=([A-Za-z0-9_-]+)$/.exec(identityPath(url));
  if (commentMatch) return {images:[],comments:await comments('/comments?comic_id='+commentMatch[1]+'&limit=9999&offset=0',options,false),commentMode:commentMode(options)};
  var id = chapterIdentity(url), result = await api('/comic/'+id.slug+'/chapter2/'+id.uuid,options), data = result.chapter;
  if (!obj(data) || data.uuid !== id.uuid || data.comic_path_word !== id.slug) fail('章节内容标识不符');
  if (!Array.isArray(data.contents) || data.contents.length === 0 || data.contents.length > 2000) fail('章节没有可读图片，可能隐藏、删除或需要授权');
  var order = data.words;
  if (order !== undefined && order !== null && (!Array.isArray(order) || (order.length && order.length !== data.contents.length))) fail('图片顺序数据不完整');
  var pages = data.contents.map(function(row,i) {
    if (!obj(row) || (order && order.length && !count(order[i]))) fail('图片顺序无效');
    return {url:imageUrl(row.url,options),index:order && order.length ? order[i] : i,position:i};
  });
  pages.sort(function(a,b) { return a.index-b.index || a.position-b.position; });
  var output = {images:pages.map(function(p) { return p.url; })};
  if (options.showChapterComments === true) {
    output.comments = await comments('/roasts?limit=100&chapter_id='+id.uuid,options,true);
    output.commentMode = commentMode(options);
  }
  return output;
}
